            var route=RoadDemoRoute.Build(session.World.Route.Region,Vector3.zero);float selected=-1;for(float d=8;d<Mathf.Min(route.Length-60,600);d+=8){var f=route.Forward(d);if(Mathf.Abs(f.y)<.10f&&new[]{10f,20f,30f}.All(delta=>Vector3.Angle(f,route.Forward(d+delta))<6)){selected=d;break;}}Require(selected>=8,"No bounded straight useful road pose found");
