            double warm=Time.realtimeSinceStartupAsDouble;while(Time.realtimeSinceStartupAsDouble-warm<2.5)yield return new WaitForEndOfFrame();Require(session.Conditions.Hour<3&&session.Car.Visual.Headlights.All(l=>l&&l.enabled),"Actual automatic night headlights must already be enabled");Require(session.Profile.garage.Active.model==requestedModel,"Actual garage selection differs from requested model");Require(!requestedRain||session.Conditions.Rain>.7f&&session.Conditions.Wetness>.99f&&Mathf.Abs(session.World.Asphalt.GetFloat("_Smoothness")-.79f)<.001f,"Regular weather update must apply rain/wet road material before freezing");session.Conditions.enabled=false;session.View.enabled=false;camera=session.View.GetComponent<Camera>();lights=session.Car.Visual.Headlights;original=lights.Select(State).ToArray();Require(original.Length==2&&original.All(l=>Mathf.Abs(l.intensity-HeadlightTuning.Intensity)<.001f),"Production lights must use shared configured intensity");carPosition=session.Car.Body.position;carRotation=session.Car.Body.rotation;cameraPosition=camera.transform.position;cameraRotation=camera.transform.rotation;cameraFov=camera.fieldOfView;fixedHour=session.Conditions.Hour;fixedRain=session.Conditions.Rain;fixedWetness=session.Conditions.Wetness;exposure=Exposure();ambientSky=RenderSettings.ambientSkyColor;skyExposure=RenderSettings.skybox&&RenderSettings.skybox.HasProperty("_Exposure")?RenderSettings.skybox.GetFloat("_Exposure"):0;
            foreach(float ahead in new[]{5f,10f,20f,30f})foreach(float offset in new[]{-1f,0f,1f}){var p=route.At(selected+ahead,route.LaneOffset(selected+ahead)+offset);p.y=session.World.Route.Region.RoadSurfaceHeight(p.x,p.z)+.03f;samplePoints.Add(p);}
