            OcclusionGeometry("production");RestoreLights();
            var pipeline=GraphicsSettings.currentRenderPipeline as UniversalRenderPipelineAsset;report.pipeline=pipeline?pipeline.name:"unknown";report.additionalLightShadowsSupported=pipeline&&pipeline.supportsAdditionalLightShadows;report.additionalLightsRenderingMode=pipeline?pipeline.additionalLightsRenderingMode.ToString():"unknown";report.additionalLightsPerObject=pipeline?pipeline.maxAdditionalLightsCount:-1;report.nearbyActiveLights=FindObjectsByType<Light>(FindObjectsSortMode.None).Count(l=>l.enabled&&l.gameObject.activeInHierarchy&&Vector3.Distance(l.transform.position,carPosition)<110);
